count = 0

for x in range(4):
    number = int(input("Enter a number: "))
    if number > 10:
        count = count + 1

print("Numbers greater than 10: " + str(count))

passes = 0
fails = 0

for x in range(5):
    score = int(input("Enter a score: "))
    if score >= 50:
        passes = passes + 1
    else:
        fails = fails + 1

print("Passes: " + str(passes))
print("Fails: " + str(fails))

hotDays = 0
freezingDays = 0

for x in range(7):
    temp = int(input("Enter the temperature for day " + str(x + 1) + ": "))
    if temp > 15:
        hotDays = hotDays + 1
    elif temp < 0:
        freezingDays = freezingDays + 1

print("Hot days (above 15°C): " + str(hotDays))
print("Freezing days (below 0°C): " + str(freezingDays))
